import{_ as a,o as e,c as l,a2 as d}from"./chunks/framework.Crpw6aS5.js";const u=JSON.parse('{"title":"桌面端更新","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/10-release-auto-update.md","filePath":"desktop/10-release-auto-update.md","lastUpdated":1784192334000}'),i={name:"desktop/10-release-auto-update.md"};function o(r,t,s,n,h,p){return e(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="桌面端更新" tabindex="-1">桌面端更新 <a class="header-anchor" href="#桌面端更新" aria-label="Permalink to &quot;桌面端更新&quot;">​</a></h1><p>EchoFlow Code 会在启动后检查新版本。你也可以在设置中手动检查、下载并安装更新。</p><h2 id="支持的平台" tabindex="-1">支持的平台 <a class="header-anchor" href="#支持的平台" aria-label="Permalink to &quot;支持的平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>首次安装</th><th>应用内更新</th></tr></thead><tbody><tr><td>macOS</td><td>下载与你的芯片匹配的 DMG</td><td>支持</td></tr><tr><td>Windows</td><td>下载 Windows 安装程序</td><td>支持</td></tr><tr><td>Linux</td><td>AppImage 或 DEB</td><td>AppImage 支持；DEB 请手动更新</td></tr></tbody></table><p>更新由 GitHub Releases 提供。下载前请确认发布页面属于 EchoFlow Code 项目，并选择与系统和处理器架构匹配的安装包。</p><h2 id="检查更新" tabindex="-1">检查更新 <a class="header-anchor" href="#检查更新" aria-label="Permalink to &quot;检查更新&quot;">​</a></h2><ol><li>打开设置中的更新页面。</li><li>点击检查更新。</li><li>有新版本时，按提示下载。</li><li>下载完成后安装并重启应用。</li></ol><p>更新不会主动删除本地会话、Provider 配置、Skills、记忆或自定义数据目录。重要项目仍建议使用 Git，并按自己的备份策略保护本地配置。</p><h2 id="系统安全提示" tabindex="-1">系统安全提示 <a class="header-anchor" href="#系统安全提示" aria-label="Permalink to &quot;系统安全提示&quot;">​</a></h2><ul><li>macOS 未签名构建可能需要按发布说明手动放行。优先使用已签名并完成公证的版本。</li><li>Windows 未签名构建可能触发 SmartScreen。请先核对下载来源和版本，再决定是否继续。</li><li>Linux AppImage 首次下载后可能需要添加可执行权限。</li></ul><h2 id="更新失败" tabindex="-1">更新失败 <a class="header-anchor" href="#更新失败" aria-label="Permalink to &quot;更新失败&quot;">​</a></h2><p>遇到更新失败时，可以：</p><ol><li>退出并重新打开应用后再次检查。</li><li>检查网络是否能访问 GitHub Releases。</li><li>确认磁盘空间充足，且安装目录没有被安全软件锁定。</li><li>从最新 Release 手动下载安装包覆盖安装。</li></ol><p>手动覆盖安装前不要删除应用数据目录；直接替换应用程序通常可以保留现有数据。</p>',14)])])}const _=a(i,[["render",o]]);export{u as __pageData,_ as default};
